INSERT INTO departamento (id_pais, codigo, nombre) SELECT p.id_pais, '1', 'Guatemala' FROM pais p WHERE UPPER(p.nombre)=UPPER('Guatemala') AND NOT EXISTS (SELECT 1 FROM departamento d WHERE d.codigo='1' OR UPPER(d.nombre)=UPPER('Guatemala'));
